  animation-name:gold-stardust-lap;
  animation-duration:12s;
  animation-timing-function:linear;
  animation-iteration-count:infinite;
}
.gold-trail i::before{content:'✦';display:block}
.gold-trail i:nth-child(1){width:6px;height:6px;font-size:8px;animation-delay:0s;opacity:0}
.gold-trail i:nth-child(2){width:5px;height:5px;font-size:6px;animation-delay:.06s;transform:none;filter:none;opacity:0}
.gold-trail i:nth-child(3){width:4px;height:4px;font-size:5px;animation-delay:.12s;transform:none;filter:none;opacity:0}
.gold-trail i:nth-child(4){width:3px;height:3px;font-size:4px;animation-delay:.18s;transform:none;filter:none;opacity:0}
.gold-trail i:nth-child(5){width:2px;height:2px;font-size:3px;animation-delay:.24s;transform:none;filter:none;opacity:0}
@keyframes gold-stardust-lap{
  0%{offset-distance:0%;opacity:0}
  .8%{opacity:1}
  14.5%{opacity:1}
  16.67%{offset-distance:100%;opacity:0}
  100%{offset-distance:100%;opacity:0}
}


