/* Ver.0.7.1 single cycling MARK control */
.marks.mark-cycle{display:flex;align-items:center;gap:7px}
.marks.mark-cycle label{display:flex;flex-direction:column;align-items:flex-end;line-height:1.05}
.marks.mark-cycle label small{font-size:.48rem;letter-spacing:0;color:#9b7a67;font-weight:700;white-space:nowrap}
#modeCycle{min-width:40px;font-size:1rem;font-weight:900;transition:background .16s ease,color .16s ease,border-color .16s ease,transform .12s ease}
#modeCycle:active{transform:scale(.93)}
#modeCycle[data-mode="x"]{background:#ef9d58;color:#fff;border-color:#d77c31}
#modeCycle[data-mode="q"]{background:#7ea7d7;color:#fff;border-color:#5d87ba}
#modeCycle[data-mode="t"]{background:#9d82c7;color:#fff;border-color:#7d62a8}
.training{line-height:1.3}


/* Ver.0.7.2 unified soft white puzzle marks */
.tile .mark-x,.tile .mark-q,.tile .mark-t{
  color:#fff!important;
  font-family:"Arial Rounded MT Bold","M PLUS Rounded 1c","Zen Maru Gothic","Hiragino Maru Gothic ProN",sans-serif!important;
  font-weight:900!important;
  line-height:1!important;
  -webkit-text-stroke:0!important;
  paint-order:normal!important;
  text-shadow:0 1px 2px rgba(75,61,78,.28)!important;
  filter:none!important;
}
.tile .mark-x{
  font-size:clamp(2rem,11vw,3.35rem)!important;
  transform:scaleX(.92);
}
.tile .mark-q{
  font-size:clamp(1.75rem,9.8vw,3rem)!important;
  transform:translateY(-1px);
}
.tile .mark-t{
  font-size:clamp(1.85rem,10vw,3.1rem)!important;
  transform:scaleX(1.06) translateY(-1px);
}
/* The MARK switch itself also uses the same soft white visual language. */
#modeCycle{
  color:#fff!important;
  font-family:"Arial Rounded MT Bold","M PLUS Rounded 1c","Zen Maru Gothic","Hiragino Maru Gothic ProN",sans-serif!important;
  -webkit-text-stroke:0!important;
  text-shadow:0 1px 1px rgba(68,50,63,.2)!important;
}


/* Ver.0.7.3 custom rounded SVG marks */
.mark-symbol{display:inline-grid;place-items:center;width:82%;height:82%;color:#fff;pointer-events:none}
.mark-symbol svg{display:block;width:100%;height:100%;overflow:visible}
.mark-symbol .mark-outline,.mark-symbol .mark-core{fill:none;stroke-linecap:round;stroke-linejoin:round}
.mark-symbol .mark-outline{stroke:rgba(64,53,59,.42);stroke-width:9}
.mark-symbol .mark-core{stroke:#fff;stroke-width:6.2}
.mark-symbol .mark-core circle{fill:#fff!important}
.mark-symbol .mark-outline circle{fill:rgba(64,53,59,.42)!important;stroke:none}
.mark-symbol.mark-q{width:73%;height:73%}
.mark-symbol.mark-t{width:78%;height:78%}
.mark-symbol.mark-small{width:25px;height:25px}
#modeCycle .mark-symbol{color:#fff}
/* Disable older font-glyph mark presentation when SVG symbols are present. */
.tile>.mark-symbol{font-size:0!important;transform:none!important;text-shadow:none!important}

/* Ver.0.7.3.1: single SVG X and unified outline */
/* Legacy CSS X layers must not be drawn behind the current SVG mark. */
.tile > .mark-symbol.mark-x::before,
.tile > .mark-symbol.mark-x::after,
#modeCycle .mark-symbol.mark-x::before,
#modeCycle .mark-symbol.mark-x::after {
  content: none !important;
  display: none !important;
  background: none !important;
  background-image: none !important;
  box-shadow: none !important;
}

/* Remove the old background-image X and let the SVG be the only visible X. */
.tile > .mark-symbol.mark-x,
#modeCycle .mark-symbol.mark-x {
  position: relative !important;
  inset: auto !important;
  left: auto !important;
  top: auto !important;
  width: 82% !important;
  height: 82% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  transform: none !important;
  translate: none !important;
  overflow: visible !important;
  background: none !important;
  background-image: none !important;
  filter: none !important;
}

/* Use exactly the same stroke values as the approved ? and triangle SVG marks. */
.mark-symbol.mark-x .mark-outline {
  stroke: rgba(64,53,59,.42) !important;
  stroke-width: 9 !important;
}
.mark-symbol.mark-x .mark-core {
  stroke: #fff !important;
  stroke-width: 6.2 !important;
}
/* End Ver.0.7.3.1 */

/* Ver.0.7.3.2: X size balance */
/* The X path uses a smaller part of its 64x64 viewBox than ? and triangle,
   so enlarge only the X container to match their visible size. */
.tile > .mark-symbol.mark-x {
  width: 96% !important;
  height: 96% !important;
}

/* Keep the MARK switch X balanced with the other two switch symbols too. */
#modeCycle .mark-symbol.mark-x {
  width: 29px !important;
  height: 29px !important;
}
/* End Ver.0.7.3.2 */

/* Ver.0.7.3.3: X visual balance */
/* Increase the X's visible footprint and white stroke to match ? and triangle. */
.tile > .mark-symbol.mark-x {
  width: 104% !important;
  height: 104% !important;
}

.mark-symbol.mark-x .mark-outline {
  stroke-width: 10.4 !important;
}

.mark-symbol.mark-x .mark-core {
  stroke-width: 7.4 !important;
}

/* Keep the switch-button X visually balanced as well. */
#modeCycle .mark-symbol.mark-x {
  width: 31px !important;
  height: 31px !important;
}
/* End Ver.0.7.3.3 */

/* Ver.0.7.5: compact heart help and Taiju hint presentation */
.life-help-host{position:relative;cursor:help;outline:none}
.heart-help-pop{display:none;position:absolute;left:0;top:calc(100% + 7px);z-index:320;width:min(270px,78vw);padding:9px 11px;border:1px solid #dfc6ad;border-radius:12px;background:#fffaf2;color:#67564c;font-size:.72rem;font-weight:700;line-height:1.55;box-shadow:0 8px 22px rgba(74,53,40,.2)}
.life-help-host:hover .heart-help-pop,.life-help-host:focus .heart-help-pop,.heart-help-pop.open{display:block}
