body.hint-casting::after{content:"";position:fixed;inset:0;z-index:250;background:rgba(42,53,61,.34);pointer-events:none;animation:hintCastShade .42s ease forwards}
@keyframes hintCastShade{0%{opacity:0}45%{opacity:1}100%{opacity:0}}
