.tile.hint-safe-x,.tile.hint-safe-x.clp-hint-x{border-color:#138ad1!important;outline:4px solid #138ad1!important;box-shadow:0 0 0 4px rgba(19,138,209,.38),0 0 25px 12px rgba(54,173,239,.72)!important;animation:nmForceBlueBreath 1s ease-in-out infinite!important}
.tile.hint-safe-x::after{content:"×"!important;color:#087fc7!important;font:900 clamp(2.8rem,11vw,4.6rem)/1 "Arial Rounded MT Bold","Arial",sans-serif!important;-webkit-text-stroke:1.5px rgba(255,255,255,.98)!important;text-shadow:0 0 7px #fff,0 0 17px #23a9ef!important}
@media(max-width:430px){.heart-help-pop{left:-4px;width:min(255px,82vw)}}
/* End Ver.0.7.5 */

/* Ver.0.7.6: floating cat-teaser confirmation and larger X */
.toy-ready-layer{position:fixed;inset:0;z-index:1250;background:rgba(30,38,42,.12);backdrop-filter:brightness(.92);display:grid;place-items:center;opacity:0;transition:opacity .2s ease}
.toy-ready-layer.show{opacity:1}
.toy-ready-feather{border:0;background:transparent;display:grid;place-items:center;gap:8px;color:#fff;filter:drop-shadow(0 9px 14px rgba(37,43,50,.36));cursor:pointer;animation:toyFeatherFloat 1.7s ease-in-out infinite}
.toy-ready-feather span{display:grid;place-items:center;width:112px;height:112px;border-radius:50%;font-size:4.7rem;background:rgba(255,255,255,.82);box-shadow:0 0 0 5px rgba(255,255,255,.42),0 12px 35px rgba(61,103,126,.32)}
.toy-ready-feather small{padding:6px 12px;border-radius:999px;background:rgba(54,65,72,.72);font-size:.82rem;font-weight:900;letter-spacing:.04em}
.toy-ready-feather:active{transform:scale(.94)}
@keyframes toyFeatherFloat{0%,100%{transform:translateY(7px) rotate(-5deg)}50%{transform:translateY(-10px) rotate(5deg)}}
/* The X is intentionally 1.2 times the previous 104% visual size. */
.tile>.mark-symbol.mark-x{width:124.8%!important;height:124.8%!important}
#modeCycle .mark-symbol.mark-x{width:37.2px!important;height:37.2px!important}
/* End Ver.0.7.6 */

/* Ver.0.7.7: center the enlarged mark inside the mode button */
#modeCycle{position:relative!important;display:grid!important;place-items:center!important;padding:0!important;overflow:hidden!important}
#modeCycle .mark-symbol{position:absolute!important;left:50%!important;top:50%!important;margin:0!important;transform:translate(-50%,-50%)!important;transform-origin:center!important}
#modeCycle .mark-symbol.mark-x{width:37.2px!important;height:37.2px!important}
#modeCycle .mark-symbol.mark-q,#modeCycle .mark-symbol.mark-t{width:31px!important;height:31px!important}
/* End Ver.0.7.7 */

/* Ver.0.7.8: interactive heart recovery panel */
.heart-help-pop{cursor:default;min-width:250px;text-align:left}
.heart-help-pop .heart-countdown{display:inline-block;margin:4px 0;color:#d56c38;font-weight:900;font-variant-numeric:tabular-nums}
.heart-kibble-recover{display:block;width:100%;margin-top:9px;padding:8px 10px;border:1px solid #dc9e65;border-radius:10px;background:linear-gradient(#fff4d9,#ffe3ae);color:#86512f;font:900 .74rem/1.2 inherit;cursor:pointer;box-shadow:0 2px 5px rgba(104,68,39,.14)}
.heart-kibble-recover:active:not(:disabled){transform:scale(.97)}
.heart-kibble-recover:disabled{opacity:.55;cursor:not-allowed;box-shadow:none}
/* Keep the panel open while its recovery button is being tapped. */
.heart-help-pop,.heart-help-pop *{pointer-events:auto}
/* End Ver.0.7.8 */

